impl Document {
    pub(crate) fn compare_analyzed_execution_time(
        &self,
        other: &Document,
        a: &AnalyzedExecutionTime,
        b: &AnalyzedExecutionTime,
        path: &str,
    ) -> Result<(), String> {
        self.compare_execution_time(other, a.base(), b.base(), path)?;
        if a.get_best_case_execution_time() != b.get_best_case_execution_time() {
            return Err(format!("{path}: BEST_CASE_EXECUTION_TIME mismatch"));
        }
        if a.get_worst_case_execution_time() != b.get_worst_case_execution_time() {
            return Err(format!("{path}: WORST_CASE_EXECUTION_TIME mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_execution_time(
        &self,
        other: &Document,
        a: &ExecutionTime,
        b: &ExecutionTime,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_exclusive_area_ref() != b.get_exclusive_area_ref() {
            return Err(format!("{path}: EXCLUSIVE_AREA_REF mismatch"));
        }
        if a.get_executable_entity_ref() != b.get_executable_entity_ref() {
            return Err(format!("{path}: EXECUTABLE_ENTITY_REF mismatch"));
        }
        if a.get_hardware_configuration() != b.get_hardware_configuration() {
            return Err(format!("{path}: HARDWARE_CONFIGURATION mismatch"));
        }
        if a.get_hw_element_ref() != b.get_hw_element_ref() {
            return Err(format!("{path}: HW_ELEMENT_REF mismatch"));
        }
        let list_a = a.get_included_library_refs();
        let list_b = b.get_included_library_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: INCLUDED_LIBRARY_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.INCLUDED_LIBRARY_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.INCLUDED_LIBRARY_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.INCLUDED_LIBRARY_REFS[{index}]"),
            )?;
        }
        let list_a = a.get_memory_section_locations();
        let list_b = b.get_memory_section_locations();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MEMORY_SECTION_LOCATIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.memory_section_locations.get(*x).ok_or_else(|| {
                format!("{path}.MEMORY_SECTION_LOCATIONS[{index}]: id not found in own arena")
            })?;
            let y = other.memory_section_locations.get(*y).ok_or_else(|| {
                format!("{path}.MEMORY_SECTION_LOCATIONS[{index}]: id not found in other arena")
            })?;
            self.compare_memory_section_location(
                other,
                x,
                y,
                &format!("{path}.MEMORY_SECTION_LOCATIONS[{index}]"),
            )?;
        }
        if a.get_software_context() != b.get_software_context() {
            return Err(format!("{path}: SOFTWARE_CONTEXT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_measured_execution_time(
        &self,
        other: &Document,
        a: &MeasuredExecutionTime,
        b: &MeasuredExecutionTime,
        path: &str,
    ) -> Result<(), String> {
        self.compare_execution_time(other, a.base(), b.base(), path)?;
        if a.get_maximum_execution_time() != b.get_maximum_execution_time() {
            return Err(format!("{path}: MAXIMUM_EXECUTION_TIME mismatch"));
        }
        if a.get_minimum_execution_time() != b.get_minimum_execution_time() {
            return Err(format!("{path}: MINIMUM_EXECUTION_TIME mismatch"));
        }
        if a.get_nominal_execution_time() != b.get_nominal_execution_time() {
            return Err(format!("{path}: NOMINAL_EXECUTION_TIME mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_memory_section_location(
        &self,
        _other: &Document,
        a: &MemorySectionLocation,
        b: &MemorySectionLocation,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_provided_memory_ref() != b.get_provided_memory_ref() {
            return Err(format!("{path}: PROVIDED_MEMORY_REF mismatch"));
        }
        if a.get_software_memory_section_ref() != b.get_software_memory_section_ref() {
            return Err(format!("{path}: SOFTWARE_MEMORY_SECTION_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_rough_estimate_of_execution_time(
        &self,
        other: &Document,
        a: &RoughEstimateOfExecutionTime,
        b: &RoughEstimateOfExecutionTime,
        path: &str,
    ) -> Result<(), String> {
        self.compare_execution_time(other, a.base(), b.base(), path)?;
        if a.get_additional_information() != b.get_additional_information() {
            return Err(format!("{path}: ADDITIONAL_INFORMATION mismatch"));
        }
        if a.get_estimated_execution_time() != b.get_estimated_execution_time() {
            return Err(format!("{path}: ESTIMATED_EXECUTION_TIME mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_simulated_execution_time(
        &self,
        other: &Document,
        a: &SimulatedExecutionTime,
        b: &SimulatedExecutionTime,
        path: &str,
    ) -> Result<(), String> {
        self.compare_execution_time(other, a.base(), b.base(), path)?;
        if a.get_maximum_execution_time() != b.get_maximum_execution_time() {
            return Err(format!("{path}: MAXIMUM_EXECUTION_TIME mismatch"));
        }
        if a.get_minimum_execution_time() != b.get_minimum_execution_time() {
            return Err(format!("{path}: MINIMUM_EXECUTION_TIME mismatch"));
        }
        if a.get_nominal_execution_time() != b.get_nominal_execution_time() {
            return Err(format!("{path}: NOMINAL_EXECUTION_TIME mismatch"));
        }
        Ok(())
    }
}
